{
  "avaliacoes": [
    {
      "id": "Efdfe9a69b4091453",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A fonte indica que cabeçalhos de flare devem dispor de purga após paradas ou períodos com flare apagado, para deslocar ar antes da reignição e reduzir o risco de atmosfera inflamável.",
          "trechos": [
            "Efdfe9a69b4091453:0:700"
          ],
          "condicoes": [
            "Aplicável a situações de shutdown ou períodos em que o flare esteja extinto.",
            "A efetividade depende de taxa e volume de purga suficientes."
          ],
          "limites": [
            "É orientação de guia HSE e não requisito brasileiro automático.",
            "O trecho não fornece critérios de dimensionamento da purga."
          ]
        },
        {
          "proposicao": "A fonte informa que gás combustível ou nitrogênio podem ser fornecidos a alguns tanques e vasos, inclusive tanques de dreno aberto/fechado, para manter pressurização, acomodar expansão/contração, excluir ar e prevenir atmosfera explosiva ou degradação química.",
          "trechos": [
            "Efdfe9a69b4091453:0:700"
          ],
          "condicoes": [
            "Aplicável a equipamentos nos quais se deseje manter pressurização ou exclusão de ar.",
            "Inclui exemplos como tanques de metanol, glicol, vasos de expansão e tanques de dreno."
          ],
          "limites": [
            "O trecho apresenta possibilidades de arranjo, não obrigação universal para todo sistema de drenagem.",
            "Não detalha compatibilidade de gases com cada serviço ou fluido."
          ]
        },
        {
          "proposicao": "Para intervenção de manutenção e retorno ao serviço, a fonte recomenda controlar atmosferas inflamáveis por meio de purga com nitrogênio ou outro gás inerte e verificar, por amostragem após a manutenção, se o teor de oxigênio do ambiente inerte ficou abaixo do valor especificado no procedimento.",
          "trechos": [
            "Efdfe9a69b4091453:700:1398",
            "Efdfe9a69b4091453:1398:2096"
          ],
          "condicoes": [
            "Aplicável antes de intervir e ao restaurar equipamentos ao serviço.",
            "Em equipamentos onde hidrocarboneto não possa ser totalmente removido, podem ser necessárias precauções adicionais."
          ],
          "limites": [
            "A referência a teor típico de oxigênio é apresentada como exemplo do guia, dependente de procedimento especificado.",
            "Não trata de toda a lógica de alarmes, permissivos ou intertravamentos."
          ]
        }
      ]
    },
    {
      "id": "E339a40579aa65b7e",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A fonte descreve que tanques de armazenamento respiram por conjuntos automáticos de válvulas de pressão e vácuo, mas requer procedimentos de teste e uma via alternativa de ventilação caso a válvula principal falhe.",
          "trechos": [
            "E339a40579aa65b7e:0:700"
          ],
          "condicoes": [
            "Aplicável a tanques de armazenamento com respiração por válvulas de pressão/vácuo."
          ],
          "limites": [
            "O intervalo de pressões citado pertence ao exemplo do documento e não deve ser generalizado como requisito brasileiro.",
            "O trecho não cobre arranjos completos de instrumentação de nível nem de drenagem."
          ]
        },
        {
          "proposicao": "A fonte recomenda instalar rompedor de pressão/vácuo de emergência quando a válvula principal puder falhar, tratando esse equipamento como elemento crítico à segurança sujeito a testes e manutenção de rotina.",
          "trechos": [
            "E339a40579aa65b7e:0:700"
          ],
          "condicoes": [
            "Aplicável como salvaguarda para falha da válvula principal de pressão/vácuo.",
            "O equipamento deve ser dimensionado para o maior cenário plausível de sobrepressão do tanque de carga."
          ],
          "limites": [
            "É orientação de inspeção/projeto de fonte estrangeira.",
            "O trecho não informa critérios completos de desempenho nem periodicidades."
          ]
        },
        {
          "proposicao": "Quando houver sistema de hydrocarbon blanketing/recovery, a fonte recomenda procedimentos para garantir disponibilidade do sistema de gás inerte e, em caso de indisponibilidade ou falha de comutação, medidas secundárias como parada de planta e método fail-safe para assegurar rota ao flare e evitar sobrepressão.",
          "trechos": [
            "E339a40579aa65b7e:700:1391",
            "E339a40579aa65b7e:1391:2087"
          ],
          "condicoes": [
            "Aplicável a FPSOs com sistemas de blanketing/recuperação de hidrocarbonetos em tanques.",
            "Especialmente relevante quando a rota normal ao flare puder ficar bloqueada por esse arranjo."
          ],
          "limites": [
            "A menção a API RP 2FPS e SOLAS é referência normativa estrangeira, não requisito brasileiro automático.",
            "O trecho não detalha lógica de comutação, setpoints ou tempos de resposta."
          ]
        }
      ]
    },
    {
      "id": "E5b84784f1c690819",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Na abordagem de inspeção, a fonte recomenda confirmar a existência de procedimentos operacionais para ventilação de tanques de carga e para venting em condições de vento fraco.",
          "trechos": [
            "E5b84784f1c690819:699:1399"
          ],
          "condicoes": [
            "Aplicável a operações de venting de carga em FPSO."
          ],
          "limites": [
            "É lista de verificação de inspeção, não demonstração empírica de desempenho.",
            "Não define conteúdo mínimo completo desses procedimentos."
          ]
        },
        {
          "proposicao": "A fonte recomenda verificar com o operador quais ações seriam apropriadas em condições ambientais extremas que possam afetar a drenagem dos cabeçalhos de ventilação e vasos associados.",
          "trechos": [
            "E5b84784f1c690819:699:1399"
          ],
          "condicoes": [
            "Aplicável quando condições ambientais extremas puderem prejudicar a drenagem de vent headers e vasos associados."
          ],
          "limites": [
            "O trecho não especifica quais condições ambientais são governantes nem as respostas operacionais adequadas."
          ]
        },
        {
          "proposicao": "A fonte orienta verificar se o sistema de gás inerte consegue a vazão de descarga prevista, se há monitoramento do teor de oxigênio com alarmes em níveis apropriados e qual seria a resposta do operador a alto teor de oxigênio; também registra como preocupação evidente a drenagem incorreta de vent headers e do flare KO drum, com aumento de contrapressão e prejuízo à função de alívio.",
          "trechos": [
            "E5b84784f1c690819:1399:2098",
            "E5b84784f1c690819:2098:2260"
          ],
          "condicoes": [
            "Aplicável a sistemas de inertização e alívio em FPSO.",
            "Relevante quando a drenagem de vent headers ou do flare KO drum puder ser comprometida."
          ],
          "limites": [
            "A capacidade mínima citada para o sistema de gás inerte pertence ao guia e não deve ser convertida automaticamente em requisito brasileiro.",
            "O trecho não informa setpoints de alarme nem critérios detalhados de projeto de drenagem."
          ]
        }
      ]
    },
